package net.hivel.islandsrpg.boss;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.drop.DropDefinition; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.attribute.Attribute; import org.bukkit.boss.*; import org.bukkit.configuration.ConfigurationSection; import org.bukkit.configuration.file.FileConfiguration; import org.bukkit.entity.*; import org.bukkit.persistence.PersistentDataType; import java.util.*;
public class BossService { private final IslandsRPGPlugin plugin; private final Map<String,BossDefinition> bosses=new LinkedHashMap<>(); public BossService(IslandsRPGPlugin p){plugin=p;} public void reload(){FileConfiguration c=ConfigUtil.load(plugin,"bosses.yml"); bosses.clear(); var sec=c.getConfigurationSection("bosses"); if(sec==null)return; for(String id:sec.getKeys(false)){try{ConfigurationSection s=c.getConfigurationSection("bosses."+id); Map<String,DropDefinition> drops=new LinkedHashMap<>(); var ds=s.getConfigurationSection("drops"); if(ds!=null) for(String k:ds.getKeys(false)){DropDefinition d=plugin.drops().parse(k,ds.getConfigurationSection(k)); if(d!=null)drops.put(k,d);} bosses.put(id,new BossDefinition(id,EntityType.valueOf(s.getString("entity","ZOMBIE")),s.getString("display-name",id),s.getString("island","starter"),s.getInt("level",1),s.getDouble("health",100),s.getDouble("damage",1),s.getLong("xp",0),s.getLong("money",0),s.getLong("fragments",0),s.getBoolean("show-health-name",true),s.getBoolean("bossbar.enabled",true),BarColor.valueOf(s.getString("bossbar.color","PURPLE")),BarStyle.valueOf(s.getString("bossbar.style","SOLID")),s.getString("bossbar.title",s.getString("display-name",id)),s.getDouble("bossbar.range",40),drops));}catch(Exception e){plugin.getLogger().warning("Invalid boss "+id+": "+e.getMessage());}}} public Collection<BossDefinition> all(){return bosses.values();} public BossDefinition get(String id){return bosses.get(id);} public LivingEntity spawn(String id, Location loc){BossDefinition d=get(id); if(d==null||loc==null||loc.getWorld()==null)return null; Entity ent=loc.getWorld().spawnEntity(loc,d.entity()); if(!(ent instanceof LivingEntity le)){ent.remove(); return null;} le.getPersistentDataContainer().set(plugin.key("mob_id"), PersistentDataType.STRING,id); le.getPersistentDataContainer().set(plugin.key("mob_boss"), PersistentDataType.INTEGER,1); if(le.getAttribute(Attribute.MAX_HEALTH)!=null) le.getAttribute(Attribute.MAX_HEALTH).setBaseValue(d.health()); le.setHealth(d.health()); plugin.mobs().updateName(le,d.displayName(),d.health()); plugin.bossBars().create(le,d); return le;} public boolean isBoss(LivingEntity e){return e.getPersistentDataContainer().getOrDefault(plugin.key("mob_boss"),PersistentDataType.INTEGER,0)==1;} public String id(LivingEntity e){return e.getPersistentDataContainer().get(plugin.key("mob_id"),PersistentDataType.STRING);} }
